function clubCutoverRun(PDO $pdo,int $id,bool $lock=false):array{$q=$pdo->prepare('SELECT * FROM club_cutover_runs WHERE id=?'.($lock&&$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''));$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new DomainException('Příprava přechodu nebyla nalezena.');return$r;}
