 }
 $reason=clubCutoverText($reason);$pdo->beginTransaction();try{clubCutoverActor($pdo,$actor);$r=clubCutoverRun($pdo,$run,true);if((int)$r['revision']!==$expected)throw new DomainException('Registr se změnil. Obnovte náhled a zapište novou verzi.');$q=$pdo->prepare('SELECT id FROM treneri WHERE id=? AND aktivni=1'.accountingLedgerLock($pdo));$q->execute([$data['owner_trainer_id']]);if(!$q->fetchColumn())throw new DomainException('Odpovědná osoba již není aktivní.');$entries=clubCutoverEntries($pdo,$run);
