function clubCutoverAttachmentTypes():array{return['accounting_document'=>['accounting_documents','pdf_storage_key','pdf_sha256'],'expense_decision'=>['financial_decisions','storage_key','file_sha256'],'medical'=>['medical_clearance_records','storage_key','file_sha256'],'paper'=>['club_paper_records','storage_key','file_sha256'],'accounting_export'=>['accounting_export_batches','storage_key','archive_sha256']];}
