function clubCutoverCodeState():array{
 $base=dirname(__DIR__);$prefix=strtolower(str_replace('\\','/',realpath($base))).'/';$files=[];$it=new RecursiveIteratorIterator(new RecursiveCallbackFilterIterator(new RecursiveDirectoryIterator($base,FilesystemIterator::SKIP_DOTS),static function($file)use($prefix):bool{$real=$file->getRealPath();return !$file->isLink()&&$real!==false&&str_starts_with(strtolower(str_replace('\\','/',$real)),$prefix)&&(!$file->isDir()||!in_array($file->getFilename(),['.git','.codex-tmp','vendor','node_modules','output','tmp'],true));}));
 foreach($it as$file)if($file->isFile()&&strtolower($file->getExtension())==='php'){$relative=str_replace('\\','/',substr($file->getPathname(),strlen($base)+1));if($relative==='config.php'||str_ends_with($relative,'/config.php'))continue;$files[$relative]=hash_file('sha256',$file->getPathname());}ksort($files);
 $git=$base.'/.git';if(is_file($git)&&preg_match('/^gitdir:\s*(.+)$/m',file_get_contents($git),$m))$git=trim($m[1]);$head=is_file($git.'/HEAD')?trim(file_get_contents($git.'/HEAD')):'';$commit=preg_match('/^[a-f0-9]{40}$/D',$head)?$head:null;
 if(str_starts_with($head,'ref: ')){$ref=substr($head,5);$common=is_file($git.'/commondir')?realpath($git.'/'.trim(file_get_contents($git.'/commondir'))):$git;if(preg_match('~^refs/[A-Za-z0-9/._-]+$~D',$ref)&&is_file($common.'/'.$ref)){$value=trim(file_get_contents($common.'/'.$ref));if(preg_match('/^[a-f0-9]{40}$/D',$value))$commit=$value;}}
 return['git_head'=>$commit,'php_files'=>$files,'php_sha256'=>hash('sha256',clubCutoverJson($files)),'coverage'=>'Working PHP files excluding vendor, node_modules, output, tmp and configuration. Git HEAD alone does not claim a clean checkout or deployed release.'];
}
/** Actual consistent database content, never caller-supplied counts or hashes; private row values are not exposed. */
function clubCutoverCapture(PDO $pdo):array{
 $own=!$pdo->inTransaction();if($own){if($pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql')$pdo->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$pdo->beginTransaction();}
 try{$snapshot=['captured_at'=>gmdate('Y-m-d H:i:s'),'tables'=>[],'limitations'=>[]];$mysql=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql';foreach(clubCutoverCriticalTables()as$table=>$unused){if(!accountingLedgerTable($pdo,$table)){$snapshot['tables'][$table]=['status'=>'missing'];continue;}
  if($mysql){$keys=$pdo->query("SHOW KEYS FROM `".$table."` WHERE Key_name='PRIMARY'")->fetchAll(PDO::FETCH_ASSOC);usort($keys,static fn($a,$b)=>(int)$a['Seq_in_index']<=>(int)$b['Seq_in_index']);$primary=array_column($keys,'Column_name');$ddl=$pdo->query('SHOW CREATE TABLE `'.$table.'`')->fetch(PDO::FETCH_NUM)[1];$ddl=preg_replace('/AUTO_INCREMENT=\d+\s*/','',$ddl);}else{$keys=$pdo->query('PRAGMA table_info('.$table.')')->fetchAll(PDO::FETCH_ASSOC);$keys=array_values(array_filter($keys,static fn($r)=>(int)$r['pk']>0));usort($keys,static fn($a,$b)=>(int)$a['pk']<=>(int)$b['pk']);$primary=array_column($keys,'name');$q=$pdo->prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name=?");$q->execute([$table]);$ddl=$q->fetchColumn();}
  $order=$primary?' ORDER BY '.implode(',',array_map(static fn($c)=>'`'.str_replace('`','``',$c).'`',$primary)):'';$q=$pdo->query('SELECT * FROM `'.$table.'`'.$order.' LIMIT 100001');$rows=[];$count=0;$total=[];while($r=$q->fetch(PDO::FETCH_ASSOC)){$count++;if($count>100000)break;ksort($r);$hash=hash('sha256',serialize($r));$identity=[];foreach($primary as$key)$identity[]=$r[$key];$key=count($identity)===1&&preg_match('/^[0-9]+$/D',(string)$identity[0])?(string)$identity[0]:hash('sha256',serialize($identity?:[$hash]));if(!$primary){$suffix=0;$baseKey=$key;while(isset($rows[$key]))$key=$baseKey.':'.(++$suffix);}$rows[$key]=$hash;foreach(['amount_minor','total_minor','opening_minor','accepted_minor','physical_quantity','reserved_quantity','blocked_quantity']as$field)if(isset($r[$field]))$total[$field]=($total[$field]??0)+(int)$r[$field];}ksort($rows);if($count>100000)$snapshot['tables'][$table]=['status'=>'limit_exceeded','minimum_count'=>$count];else$snapshot['tables'][$table]=['status'=>'captured','count'=>$count,'rows'=>$rows,'sha256'=>hash('sha256',clubCutoverJson($rows)),'schema_sha256'=>hash('sha256',(string)$ddl),'totals'=>$total];}
  $snapshot['code']=clubCutoverCodeState();$snapshot['application_fingerprint']=$snapshot['code']['php_sha256'];$snapshot['limitations'][]='Otisky pokrývají explicitně vlastněné tabulky kromě metadat této přípravy. Nejsou záloha příloh, tajných klíčů ani externích systémů. Nevlastněné tabulky vyžadují inventuru správce.';if($own)$pdo->commit();return$snapshot;
 }catch(Throwable$e){if($own&&$pdo->inTransaction())$pdo->rollBack();throw$e;}
}
function clubCutoverCheckpoint(PDO $pdo,int $actor,int $run,int $expected,string $label,string $reason):int{
 clubCutoverActor($pdo,$actor);$label=clubCutoverText($label,160);$reason=clubCutoverText($reason);if($pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql')$pdo->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$pdo->beginTransaction();try{clubCutoverActor($pdo,$actor);$r=clubCutoverRun($pdo,$run,true);if((int)$r['revision']!==$expected)throw new DomainException('Registr se změnil. Obnovte stránku.');$snapshot=clubCutoverCapture($pdo);$snapshot['registry']=clubCutoverEntries($pdo,$run);$snapshot['release_reference']=$r['release_reference'];$json=clubCutoverJson($snapshot);$pdo->prepare('INSERT INTO club_cutover_checkpoints(run_id,registry_revision,label,snapshot_json,snapshot_sha256,actor_trainer_id,reason) VALUES(?,?,?,?,?,?,?)')->execute([$run,$expected,$label,$json,hash('sha256',$json),$actor,$reason]);$id=(int)$pdo->lastInsertId();$pdo->commit();return$id;}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
