function clubCutoverDelta(array $before,array $after):array{$out=['added'=>0,'changed'=>0,'removed'=>0,'tables'=>[],'unknown'=>[],'schema_changed'=>[],'code_changed'=>($before['application_fingerprint']??null)!==($after['application_fingerprint']??null)];foreach(array_unique(array_merge(array_keys($before['tables']),array_keys($after['tables'])))as$table){$a=$before['tables'][$table]??[];$b=$after['tables'][$table]??[];if(($a['status']??'')!=='captured'||($b['status']??'')!=='captured'){$out['unknown'][]=$table;continue;}if(($a['schema_sha256']??null)!==($b['schema_sha256']??null))$out['schema_changed'][]=$table;$rows=['added'=>[],'changed'=>[],'removed'=>[]];foreach($b['rows']as$id=>$hash){if(!isset($a['rows'][$id]))$rows['added'][]=(string)$id;elseif(!hash_equals($a['rows'][$id],$hash))$rows['changed'][]=(string)$id;}foreach($a['rows']as$id=>$hash)if(!isset($b['rows'][$id]))$rows['removed'][]=(string)$id;foreach(['added','changed','removed']as$key)$out[$key]+=count($rows[$key]);if(array_sum(array_map('count',$rows)))$out['tables'][$table]=$rows;}$out['rollback_mode']=($out['unknown']||$out['schema_changed'])?'blocked_unknown':(($out['added']+$out['changed']+$out['removed'])>0?'preserve_new_operations_then_forward_fix_or_controlled_return':'no_observed_business_delta_still_requires_verified_restore');$out['restore_executable']=false;return$out;}
function clubCutoverPreview(PDO $pdo,int $actor,int $run,int $checkpoint,string $gate):array{
 clubCutoverActor($pdo,$actor);if(!in_array($gate,['G0','G1','G2','G3','G4','G5','G6'],true))throw new DomainException('Neplatná brána.');$r=clubCutoverRun($pdo,$run);$c=clubCutoverCheckpointGet($pdo,$checkpoint);if((int)$c['run_id']!==$run)throw new DomainException('Snímek patří jiné přípravě.');$entries=clubCutoverEntries($pdo,$run);$blockers=[];$attachments=[];$kinds=array_count_values(array_column($entries,'kind'));if((int)$c['registry_revision']!==(int)$r['revision'])$blockers[]='Registr byl po snímku změněn. Pořiďte nový snímek.';foreach(['source','agenda','integration','check']as$kind)if(empty($kinds[$kind]))$blockers[]='Chybí vyplněný okruh: '.$kind;
