  if(!is_file(__DIR__.'/club_migration.php')||!accountingLedgerTable($pdo,'club_migration_batches')){$blockers[]=$key.': migrační evidence není dostupná.';continue;}require_once __DIR__.'/club_migration.php';try{$m=clubMigrationReport($pdo,(int)$entry['data']['batch_id']);$migrationReports[$key]=array_intersect_key($m,array_flip(['id','source_namespace','source_hash','plan_hash','state','counts','integrity_issues','synthetic_only']));if($m['state']!=='rehearsal_complete')$blockers[]=$key.': migrační dávka není dokončená ani plně posouzená.';}catch(DomainException){$blockers[]=$key.': migrační dávka není dostupná.';}
 }
 if($gate!=='G0'&&!$migrationReports)$blockers[]='Chybí ověřitelný protokol konkrétní migrační dávky.';
 $current=clubCutoverCapture($pdo);$delta=clubCutoverDelta($c['snapshot'],$current);if($delta['unknown'])$blockers[]='Některé kritické tabulky chybí nebo překročily ověřovací limit.';if($delta['schema_changed'])$blockers[]='Databázové schéma se od snímku změnilo.';if($delta['code_changed'])$blockers[]='Ověřovaný kód nebo migrace se změnily.';if($delta['added']+$delta['changed']+$delta['removed']>0)$blockers[]='Po snímku vznikly změny obchodních dat. Nejprve zachovejte rozdíl a znovu posuďte základ.';
