 return['gate'=>$gate,'status'=>'blocked','production_authorized'=>false,'human_acceptance'=>'unknown','registry_revision'=>(int)$r['revision'],'checkpoint_id'=>$checkpoint,'checkpoint_sha256'=>$c['snapshot_sha256'],'blockers'=>$blockers,'attachments'=>$attachments,'migration_reports'=>$migrationReports,'delta'=>$delta,'current_snapshot'=>$current,'technical_inventory_present'=>!empty($kinds['source'])&&!empty($kinds['agenda']),'external_actions'=>false];
}
function clubCutoverReview(PDO $pdo,int $actor,int $run,int $checkpoint,string $gate,string $reason):int{
 $reason=clubCutoverText($reason);$pdo->beginTransaction();try{clubCutoverActor($pdo,$actor);$r=clubCutoverRun($pdo,$run,true);$report=clubCutoverPreview($pdo,$actor,$run,$checkpoint,$gate);$json=clubCutoverJson($report);$pdo->prepare('INSERT INTO club_cutover_reviews(run_id,checkpoint_id,registry_revision,gate,result_json,result_sha256,actor_trainer_id,reason) VALUES(?,?,?,?,?,?,?,?)')->execute([$run,$checkpoint,$r['revision'],$gate,$json,hash('sha256',$json),$actor,$reason]);$id=(int)$pdo->lastInsertId();$pdo->commit();return$id;}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
}
